// Terminus bitmap fonts, plain tables, generated by tools/gen_font.py. Sizes 6x12 up to 16x32, normal and bold.
#pragma once
#include <stdint.h>
#include <stdbool.h>

typedef struct {
    uint8_t w, h;
    uint8_t row_bytes;     // 1 if w <= 8, else 2
    uint8_t bold;
    uint16_t count;
    const uint16_t *cps;   // sorted code points
    const uint8_t *bits;   // count * h * row_bytes, each row MSB first, left aligned
} a11_font_t;

extern const a11_font_t A11_FONTS[];
extern const int A11_FONT_COUNT;

// Glyph rows for a code point, falls back to '?' and then to NULL for blank.
const uint8_t *a11_font_glyph(const a11_font_t *f, uint16_t cp);
// Font for a size index (0 = 6x12 up to 5 = 16x32) and style.
const a11_font_t *a11_font_get(int size_index, bool bold);
#include "sdkconfig.h"
#ifdef CONFIG_A11_FONT_SMALL_ONLY
#define A11_FONT_SIZES 2
#else
#define A11_FONT_SIZES 6
#endif
